CREATE TRIGGER tax_deadline_guard_notification_history_trigger BEFORE UPDATE OF request_id, auto_request_notification_status, auto_request_notification_attempt_count, auto_request_notification_last_attempt_at, auto_request_notification_next_attempt_at, auto_request_notification_accepted_at, auto_request_notification_last_error, auto_request_notification_escalated_at ON public.tax_deadline FOR EACH ROW EXECUTE FUNCTION app.tax_deadline_guard_notification_history();
